package com.agacostays.payment.controller;
import com.agacostays.payment.dto.request.FinalBillPaymentRequest; import com.agacostays.payment.dto.response.*; import com.agacostays.payment.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/billing/payments") public class FinalBillPaymentController { private final PaymentService service; public FinalBillPaymentController(PaymentService s){service=s;} @PostMapping public ResponseEntity<ApiResponse<PaymentResponse>> pay(@Valid @RequestBody FinalBillPaymentRequest r,@RequestHeader(value="Idempotency-Key",required=false)String k){return ResponseEntity.ok(ApiResponse.ok("Final bill payment order created",service.createFinalBillPayment(r,k)));} }
